import {taskPathway,standard,inScope} from './store.mjs';
import {conditionList,renderGoalAnalysis,renderTaskVisual} from './task-goals.mjs';
import {renderTaskResources} from './task-visuals.mjs';
import {esc,url,heading,standardURL,list} from './ui.mjs';

export function renderTaskPathway(p,data){
 const scope=p.get('scope')||'all',code=data.code;
 const item=standard(code);
 const boundary=item&&!inScope(item,scope)?`<p class="tp-boundary">현재 목표: ${esc(item.level)} · ${esc(item.level==='고등학교'?item.subject:item.band)}. 선택한 목표의 과제와 조건을 표시하고 있습니다.</p>`:'';
 const route=changes=>url('hierarchy',{mode:'tasks',target:code,scope,...changes});
 const requested=p.get('taskRoute')||'';
 const selectedCase=data.cases.find(c=>c.id===p.get('taskCase'))||data.cases.find(c=>!c.superseded_by_case_ids?.length)||data.cases[0];
 const selected=selectedCase?.routes.some(r=>r.id===requested)?requested:'';
 const orderedCases=p.get('taskCase')&&selectedCase?[selectedCase,...data.cases.filter(c=>c.id!==selectedCase.id)]:[...data.cases.filter(c=>!c.superseded_by_case_ids?.length),...data.cases.filter(c=>c.superseded_by_case_ids?.length)];
 const cases=orderedCases.map(c=>{const markup=`<section class="tp-case" data-task-case="${esc(c.id)}"><header><span class="tp-tag">명시한 과제의 조건 · 자체 점검</span><h2>${esc(c.title)}</h2><p class="tp-goal">목표: ${esc(c.goal)}</p></header><div class="tp-task"><strong>대표 과제</strong><p>${esc(c.task)}</p></div>${renderTaskVisual(c.visual)}${renderTaskResources(c.resources,c.references)}<section class="tp-shared"><h3>어느 경로에서도 함께 확인할 조건</h3>${list(c.shared_conditions)}<p>수학적 가정과 필요한 수행을 확인합니다. 모두를 수업 전에 숙달해야 한다는 뜻은 아닙니다.</p></section>${c.routes.length>1?'<h3 class="tp-choice">같은 목표의 대안 경로 · OR</h3><p>아래 경로는 명시한 대표 과제의 목표를 기준으로 비교합니다. 공식 성취기준이 특정 방법의 활용을 요구하면 그 방법의 수행도 별도로 확인합니다. 한 경로의 조건을 다른 경로에 합쳐 강제하지 않습니다.</p>':'<h3 class="tp-choice">이 과제에 기록한 경로</h3>'}<div class="tp-route-grid">${c.routes.map(r=>`<details class="tp-route" data-route="${esc(r.id)}" ${!selected||selectedCase?.id!==c.id||selected===r.id?'open':''}><summary><span>${esc(r.title)}</span><small>이 경로에서 함께 확인 · AND ${r.conditions.length}개</small></summary><div class="tp-route-body"><h4>함께 필요한 조건</h4>${conditionList(r,data,scope)}<h4>설명과 수행</h4><ol>${r.steps.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol><p class="tp-result">${esc(r.result)}</p><div class="tp-probe"><h4>확인 질문</h4><p>${esc(r.diagnostic.question)}</p><h4>기대하는 설명</h4><p>${esc(r.diagnostic.expected)}</p></div><a href="${esc(route({taskCase:c.id,taskRoute:r.id}))}">이 경로를 펼쳐 보기</a></div></details>`).join('')}</div>${c.notes?`<p class="tp-note">${esc(c.notes)}</p>`:''}<p class="tp-note">독립 검토와 학생 반응 검증 전입니다. 범위는 이 대표 과제에 한정됩니다.</p></section>`;return c.superseded_by_case_ids?.length?`<details class="tp-source tp-previous-case" data-previous-case="${esc(c.id)}" ${p.get('taskCase')===c.id?'open':''}><summary>기존 과제 설계 · ${esc(c.title)}</summary><p>${esc(c.revision_note||'새 하위 목표 설계로 보강한 기존 원고입니다.')}</p>${c.superseded_by_case_ids.map(id=>`<a class="button" href="${esc(route({taskCase:id}))}">보강한 과제 보기 ↗</a>`).join('')}${markup}</details>`:markup;}).join('');
 const pilots=data.pilots.length?`<section class="tp-pilots"><h2>관련된 기존 과제별 시범</h2>${data.pilots.map(m=>`<a class="button" href="${esc(url('hierarchy',{map:m.id,scope}))}">${esc(m.title)} · ${m.route_relationship==='different_goals'?'서로 다른 목표의 분기':'같은 목표의 대안 설명'} ↗</a>`).join('')}<p>학교급을 바꾸어도 원래 시범의 조건 묶음과 경로 의미를 유지합니다.</p></section>`:'';
 const branches=data.goal_branches.length?`<section><h2>기록된 하위 목표</h2>${data.goal_branches.map(g=>`<details class="tp-source"><summary>${esc(g.goal)}</summary><h3>과제</h3><p>${esc(g.task)}</p><h3>설명</h3><p>${esc(g.solution)}</p>${g.diagnosis?`<h3>진단</h3><p>${esc(g.diagnosis.question||'')}</p><p>${esc(g.diagnosis.expected||'')}</p>`:''}</details>`).join('')}</section>`:'';
 return heading('TASKS AND CONDITIONS',data.title,'같은 목표에 이르는 경로와 그 경로에서 함께 필요한 조건을 읽습니다.')+`<p class="meta">${esc(code)}</p><blockquote class="tp-official">${esc(data.official_goal)}</blockquote><div class="cp-actions"><a class="button" href="${esc(standardURL(code))}">성취기준 상세 ↗</a><a class="button" href="${esc(url('hierarchy',{concept:data.concept_id,target:code,scope,mode:'path'}))}">기준 사이의 여러 단계 연결 ↗</a><a class="button" href="${esc(url('catalog',{scope}))}">성취기준 목록</a></div>${boundary}<div class="cp-actions"><a class="button primary" href="${esc(url('hierarchy',{mode:'goals',target:code,goal:p.get('goal')||undefined,scope}))}">이 목표의 출발·활용 연결 보기 →</a></div>${renderGoalAnalysis(data,p,route)}${cases}${pilots}${!data.cases.length?`<p class="tp-pending">아래는 기존 과제와 경로의 원고입니다. ${data.pilots.length?'관련 시범 범위 밖의 ':''}경로별 AND·대안 조건은 추가 판정이 필요합니다.</p>`:''}${branches}<details class="tp-source" ${!data.cases.length&&!data.pilots.length?'open':''}><summary>기존 대표 과제의 해설</summary><p>${esc(data.task_solution)}</p><h3>대표 과제에 기록된 조건</h3>${list(data.recorded_conditions)}</details>${data.thinking.length?`<details class="tp-source"><summary>목표를 구성하는 사고 요소 ${data.thinking.length}개</summary><p>${esc(data.scope_note)}</p><div class="tp-thinking">${data.thinking.map(t=>`<article><h3>${esc(t.label)}</h3><p>${esc(t.meaning)}</p><h4>필요한 이유</h4><p>${esc(t.reason)}</p><h4>관찰할 수행</h4><p>${esc(t.observable)}</p></article>`).join('')}</div></details>`:''}${data.source_routes.length?`<details class="tp-source"><summary>기존 설명 경로 ${data.source_routes.length}개</summary>${data.source_routes.map((r,i)=>`<section><h3>설명 경로 ${i+1}</h3><p>${esc(r)}</p></section>`).join('')}<p>이 목록의 순서나 항목 수를 AND·OR 판정으로 바꾸지 않습니다.</p></details>`:''}${data.diagnostics.length?`<details class="tp-source"><summary>기존 진단 질문 ${data.diagnostics.length}개</summary>${data.diagnostics.map(d=>`<section class="tp-probe"><h3>${esc(d.question)}</h3><p><strong>기대 설명:</strong> ${esc(d.expected)}</p>${d.followup?'<p><strong>후속 확인:</strong> '+esc(d.followup)+'</p>':''}</section>`).join('')}</details>`:''}`;
}

export async function taskPathwayPage(p){return renderTaskPathway(p,await taskPathway(p.get('target')));}
